    -- =========================================================================
    --                        WORDS FROM server/review.lua
    -- =========================================================================
    ['review.a_buyout_was_charged_and_the'] = 'a buyout was charged, and the store would neither record it nor say whether it had. The server records it, or refunds it once the contract has ended without it, by itself once the database answers; Refund does the same now, and waits while the contract is still open. An older one without that record: if the contract shows the buyout (queued or bought out), dismiss; if not, refund the payer',
    ['review.a_buyout_premium_handed_back_reached'] = 'a buyout premium handed back reached nobody: refund the payer what did not arrive',
    ['review.a_queued_buyout_kept_raising_as'] = 'a queued buyout kept raising as it was settled, and the server stopped trying: if the contract is bought out and the placer has not had the premium, pay the creator; if it ended another way, refund the payer',
    ['review.money_owed_to_a_player_could'] = 'money owed to a player could not be put on the books (the store had no line id left): pay them',
    ['review.an_anonymity_fee_owed_back_could'] = 'an anonymity fee owed back could not be credited: refund what did not arrive',
    ['review.an_informant_tip_that_could_not'] = 'an informant tip that could not be delivered was owed back, and could not be credited: refund what did not arrive',
    ['review.an_intel_purchase_was_charged_and'] = 'an intel purchase was charged and the server stopped before it finished. The server settles it by itself at the next start: kept where the purchase is on record, its price owed back to the buyer where not. Left here, it could not tell: check whether the buyer has what they paid for, and refund them if not',
    ['review.money_moved_in_or_out_of'] = 'money moved in or out of the organisation\'s Renewed-Banking account and the server stopped before the ledger recorded it. The server settles it by itself at the next start (a debit put back, a credit\'s row written, a member\'s deposit made). Left here, it could not: check the account against the ledger, as the note says',
    ['review.an_organisation_salary_left_the_funds'] = 'an organisation salary left the funds and the server stopped before it said whether the member\'s bank took it: check the member\'s bank (the transaction "crimson-hitman organisation salary"); pay them if it never arrived, else dismiss',
    ['review.escrow_was_taken_and_the_store'] = 'escrow was taken and the store would not say whether it was written. The server hands every line it took back to whom it came from by itself once the database answers; Refund does the same now. An older one without that record: lines the store has now are held or handed back already, so only what it does not have is given',
    ['review.taking_a_line_of_escrow_raised'] = 'taking a line of escrow raised, so whether it left the player is not known: check what they have, and refund it if it left them',
    ['review.escrow_taken_for_a_contract_that'] = 'escrow taken for a contract that was not placed could not be given back: refund what did not arrive',
    ['review.a_contracts_escrow_was_taken_and'] = 'a contract\'s escrow was taken, and the store would neither write the contract nor say whether it had. The server places it, with its escrow, by itself once the database answers, and tells the placer; Refund does the same now. No anonymity fee was taken for it. An older one without that record: its escrow is handed back by the server, so refund only the anonymity fee it names, where the contract does not exist',
    ['review.a_payout_reached_its_recipient_and'] = 'a payout reached its recipient, and something else settled its line as well: check nobody was paid it twice, then dismiss',
    ['review.a_player_reported_this_contract_or'] = 'a player reported this contract, or a message thread on it, from the app: read their note and the messages, deal with it in the city, then dismiss with what was done. No money is in it',
    ['review.a_contract_was_placed_or_edited'] = 'a contract was placed or edited with a low-effort reason (Roleplay: Reason quality, server/rp_reason.lua): read the reason on the contract, deal with it in the city, then dismiss with what was done. No money is in it',
    ['review.a_bodyguard_jobs_reward_was_being'] = 'a bodyguard job\'s reward was being taken from the target when the server stopped, and whether it was is not known (server/rp_protection.lua): check the target\'s account; if it was taken, refund the target, if not, dismiss with a note. The job is off the board either way, and nothing else pays it',
    ['review.a_bodyguard_jobs_share_the_guards'] = 'a bodyguard job\'s share (the guard\'s pay, or what goes back to the target) was being paid when the server stopped, or its payment raised, so whether it arrived is not known: check their account; Pay gives what the item records less what is known to have arrived, Refund with an amount gives part of it, and dismiss with a note if it arrived. Nothing else pays it',

